            h2 = Fnv(h2, W); h2 = Fnv(h2, size); h2 = Fnv(h2, releaseX); h2 = Fnv(h2, releaseZ);
            for (int c = 0; c < W * H; c++) { h2 = Fnv(h2, cellZone[c]); h2 = Fnv(h2, cellRoom[c]); }
            for (int i = 0; i < edgeH.Length; i++) h2 = Fnv(h2, edgeH[i] * 16 + edgeHOff[i]);
            for (int i = 0; i < edgeV.Length; i++) h2 = Fnv(h2, edgeV[i] * 16 + edgeVOff[i]);
            for (int r = 0; r < nRooms; r++) h2 = Fnv(h2, roomType[r]);
            fsHash = h2;
            fsPhase = 7; fsCursor = 0;
            return false;
        }
        if (fsPhase == 7)
        {
            uint h2 = fsHash;
            int e = fsCursor + FS_CHUNK < n ? fsCursor + FS_CHUNK : n;
            for (int i = fsCursor; i < e; i++) h2 = Fnv(h2, ground[i]);
            fsHash = h2;
            fsCursor = e;
            if (e >= n) fsPhase = 8;
            return false;
        }
        {
            uint h2 = fsHash;
            if (fsPhase == 8) { fsPhase = 9; fsCursor = 0; }
            int e1 = fsCursor + 120 < nEmit ? fsCursor + 120 : nEmit;
            for (int e = fsCursor; e < e1; e++)
            {
                h2 = Fnv(h2, emitDef[e]); h2 = Fnv(h2, emitX[e]); h2 = Fnv(h2, emitY[e]); h2 = Fnv(h2, emitZ[e]);
                h2 = Fnv(h2, emitYaw[e]); h2 = Fnv(h2, emitParent[e]); h2 = Fnv(h2, emitFlags[e]);
            }
            fsHash = h2; fsCursor = e1;
            if (e1 < nEmit) return false;
            mapHash = h2;
            return true;
        }
    }

    // =====================================================================================================
    // Walkways (G26): with every prop solid, each placement has to leave its room walkable
    // =====================================================================================================
    int walkStamp = 1 << 20;
    int walkBlocked;   // blocked cells of the room at the last RoomWalkable call

    // free cells of a room that may be cut off from the rest in all
    public int SealedAllowance(int room)
    {
        int a = roomCellCount[room] * GenData.SEALED_SHARE / 100;
        return a > GenData.SEALED_POCKET ? a : GenData.SEALED_POCKET;
    }

    // Is the room still walkable? The test is from a doorway cell (or any free cell outdoors) over the cells no
    // prop reaches into, in two steps (report 15, K1: a walkway is 0.91 m wide):
    //   1. the wide floor: cells that lie in a free square of 2 x 2 cells (1 m), reached from the door through
    //      such cells only;
    //   2. the narrow leftovers that hang on it: the strip beside a bed, the gap between two chairs.
    // Free floor that neither step reaches is cut off, or reached only by squeezing through a half-metre gap.
    // Small pockets of it are allowed (the corner behind a plant, the gap between a fire and its seats): none
    // larger than SEALED_POCKET cells, and SealedAllowance in all.
    bool RoomWalkable(int room)
    {
        hq_RoomWalkable_room = room;
        PhSubReset();
        bool fin = false;
        while (!fin) { PhPush(); RoomWalkable_Body(); fin = PhAdvance(); PhPop(); }
        return hq_RoomWalkable_ret;
    }

    // RoomWalkable in phases, a step a call (autophase4); RoomWalkable() above runs them to the end
    void RoomWalkable_Body()
    {
        planMax = 3;
        if (planPhase == 0)
        {
            int room = hq_RoomWalkable_room;
            int s = roomCellStart[room], n = roomCellCount[room];
            BuildWide(room);
            hq_RoomWalkable_room = room;
            hq_RoomWalkable_s = s;
            hq_RoomWalkable_n = n;
        }
        if (planPhase == 1)
        {
            int s = hq_RoomWalkable_s;
            int n = hq_RoomWalkable_n;
            // @cut
            int start = -1, free = 0;
            for (int k = s; k < s + n; k++)
            {
                int i = roomCells[k];
                if (solid[i] > 0) continue;
                free++;
                bool better = start < 0;
                if (!better)
                {
                    bool dNew = (tags[i] & GenData.T_DOOR_CLEAR) != 0, dOld = (tags[start] & GenData.T_DOOR_CLEAR) != 0;
                    better = dNew && !dOld;
                    if (!better && dNew == dOld && wideMark[start] != wideStamp && wideMark[i] == wideStamp) better = true;
                }
                if (better) start = i;
            }
            walkBlocked = n - free;
            if (start < 0) { hq_RoomWalkable_ret = false; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_start = start; hq_RoomWalkable_free = free; PhEnd(); return; }
            int seen = 0;
            hq_RoomWalkable_s = s;
            hq_RoomWalkable_n = n;
            hq_RoomWalkable_start = start;
            hq_RoomWalkable_free = free;
            hq_RoomWalkable_seen = seen;
        }
        if (planPhase == 2 && PhLoop(2, 100000))
        {
            if (!PhSubActive())
            {
                int round = planIter;
                if (!(round < 3)) PhBreak();
                else { hq_RoomWalkable_round = round; PhSubBegin(); }
            }
            if (PhSubActive())
            {
                PhPush(); RoomWalkable_L1(); bool fin = PhAdvance(); PhPop();
                if (fin) PhSubEnd(); else PhStay();
                if (phBreak) { phBreak = false; PhBreak(); }
                if (phReturn) { phReturn = false; PhEnd(); return; }
            }
        }
        if (planPhase == 3)
        {
            int room = hq_RoomWalkable_room;
            int s = hq_RoomWalkable_s;
            int n = hq_RoomWalkable_n;
            int free = hq_RoomWalkable_free;
            int seen = hq_RoomWalkable_seen;
            // @cut
            if (!ExitsJoined(room)) { hq_RoomWalkable_ret = false; hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; PhEnd(); return; }
            if (seen == free) { hq_RoomWalkable_ret = true; hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; PhEnd(); return; }
            if (free - seen > SealedAllowance(room)) { hq_RoomWalkable_ret = false; hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; PhEnd(); return; }
            for (int k = s; k < s + n; k++)
            {
                int i = roomCells[k];
                if (solid[i] > 0 || dist[i] == walkStamp) continue;
                if (FloodRoom(room, i, 0) > GenData.SEALED_POCKET) { hq_RoomWalkable_ret = false; hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; PhEnd(); return; }
            }
            { hq_RoomWalkable_ret = true; hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; PhEnd(); return; }
            hq_RoomWalkable_room = room;
            hq_RoomWalkable_s = s;
            hq_RoomWalkable_n = n;
            hq_RoomWalkable_free = free;
            hq_RoomWalkable_seen = seen;
        }
    }
    void RoomWalkable_L1()
    {
        planMax = 1;
        if (planPhase == 0)
        {
            int room = hq_RoomWalkable_room;
            int start = hq_RoomWalkable_start;
            int seen = hq_RoomWalkable_seen;
            walkStamp++;
            seen = FloodRoom(room, start, walkNarrow ? 0 : 1);
            hq_RoomWalkable_room = room;
            hq_RoomWalkable_start = start;
            hq_RoomWalkable_seen = seen;
        }
        if (planPhase == 1)
        {
            int room = hq_RoomWalkable_room;
            int s = hq_RoomWalkable_s;
            int n = hq_RoomWalkable_n;
            int start = hq_RoomWalkable_start;
            int free = hq_RoomWalkable_free;
            int seen = hq_RoomWalkable_seen;
            // @cut
            // the narrow leftovers that hang on the wide floor
            int qh = 0, qt = 0;
            for (int k = s; k < s + n; k++) if (dist[roomCells[k]] == walkStamp) queue[qt++] = roomCells[k];
            while (qh < qt)
            {
                int i = queue[qh++];
                int ix = i % IW, iz = i / IW, j;
                if (iz + 1 < IH) { j = i + IW; if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && wideMark[j] != wideStamp) { dist[j] = walkStamp; queue[qt++] = j; seen++; } }
                if (ix + 1 < IW) { j = i + 1; if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && wideMark[j] != wideStamp) { dist[j] = walkStamp; queue[qt++] = j; seen++; } }
                if (iz > 0) { j = i - IW; if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && wideMark[j] != wideStamp) { dist[j] = walkStamp; queue[qt++] = j; seen++; } }
                if (ix > 0) { j = i - 1; if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && wideMark[j] != wideStamp) { dist[j] = walkStamp; queue[qt++] = j; seen++; } }
            }
            if (seen * 2 >= free || (tags[start] & GenData.T_DOOR_CLEAR) != 0) { hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_start = start; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; phBreak = true; PhEnd(); return; }
            // an area without a door (outdoors) was entered in a small corner: start again in the rest of it
            int other = -1;
            for (int k = s; k < s + n && other < 0; k++)
            {
                int i = roomCells[k];
                if (solid[i] == 0 && dist[i] != walkStamp && wideMark[i] == wideStamp) other = i;
            }
            if (other < 0) { hq_RoomWalkable_room = room; hq_RoomWalkable_s = s; hq_RoomWalkable_n = n; hq_RoomWalkable_start = start; hq_RoomWalkable_free = free; hq_RoomWalkable_seen = seen; phBreak = true; PhEnd(); return; }
            start = other;
            hq_RoomWalkable_room = room;
            hq_RoomWalkable_s = s;
            hq_RoomWalkable_n = n;
            hq_RoomWalkable_start = start;
            hq_RoomWalkable_free = free;
            hq_RoomWalkable_seen = seen;
        }
    }


    // FillToMinimum: a small outdoor area that is still below its minimum only has to stay passable (gaps of one
    // cell count): it is open to its neighbours, and the map-wide check (Validate) keeps every part reachable
    bool walkNarrow;

    // Every way out of the room (a doorway, an open side towards another outdoor area) leads from the floor the
    // walkway test has just marked, not from a cut-off pocket: a room is entered from its neighbours, so a pocket
    // that holds the only way in would seal the rest of the room off from the map.
    int[] exitAll = new int[24], exitMain = new int[24];

    // per room: its cells' steps into a neighbouring room (cell, neighbour), built on first use
    int[] exitStart, exitCount, exitCell, exitTo;
    int exitN;

    void ResetExits()
    {
        if (exitStart == null || exitStart.Length < 400) { exitStart = new int[400]; exitCount = new int[400]; }
        for (int r = 0; r < exitStart.Length; r++) exitStart[r] = -1;
        if (exitCell == null || exitCell.Length < IW * IH) { exitCell = new int[IW * IH]; exitTo = new int[IW * IH]; }
        exitN = 0;
    }

    void ListExits(int room)
    {
        exitStart[room] = exitN; exitCount[room] = 0;
        int s = roomCellStart[room], n = roomCellCount[room];
        for (int k = s; k < s + n; k++)
        {
            int i = roomCells[k];
            int ix = i % IW, iz = i / IW;
            for (int d = 0; d < 4; d++)
            {
                int jx = ix + DX[d], jz = iz + DZ[d];
                if (jx < 0 || jz < 0 || jx >= IW || jz >= IH) continue;
                int j = jz * IW + jx, other = innerRoom[j];
                if (other == room || other < 0 || !CanStep(ix, iz, d)) continue;
                if (exitN >= exitCell.Length) return;
                exitCell[exitN] = i; exitTo[exitN] = j; exitN++; exitCount[room]++;
            }
            int lk = link[i];   // a stair to another level
            if (lk >= 0 && innerRoom[lk] >= 0 && innerRoom[lk] != room && exitN < exitCell.Length) { exitCell[exitN] = i; exitTo[exitN] = lk; exitN++; exitCount[room]++; }
        }
    }

    bool ExitsJoined(int room)
    {
        int nAll = 0, nMain = 0;
        // only the room's border cells can have a way out: their steps into other rooms, listed once per room
        // (the rooms and their walls do not change while it is furnished), in the order the cells come
        if (exitStart[room] < 0) ListExits(room);
        int e0 = exitStart[room], e1 = e0 + exitCount[room];
        for (int x = e0; x < e1; x++)
        {
            int i = exitCell[x], j = exitTo[x], other = innerRoom[j];
            if (solid[i] > 0 || solid[j] > 0) continue;
            {
                bool main = dist[i] == walkStamp, have = false;
                for (int q = 0; q < nAll && !have; q++) have = exitAll[q] == other;
                if (!have && nAll < exitAll.Length) exitAll[nAll++] = other;
                if (!main) continue;
                have = false;
                for (int q = 0; q < nMain && !have; q++) have = exitMain[q] == other;
                if (!have && nMain < exitMain.Length) exitMain[nMain++] = other;
            }
        }
        return nMain == nAll;
    }

    // does the free cell lie in a free square of 2 x 2 cells of its room?
    // The wide floor of the room, all at once (the same cells WideCell finds one by one, without a call per
    // cell: the walkability test runs after every placement, and in Udon calls are what cost): every free 2 x 2
    // square of the room marks its four cells with wideStamp. Valid until the room's props change.
    int[] wideMark;
    int wideStamp;

    void BuildWide(int room)
    {
        wideStamp++;
        int s = roomCellStart[room], n = roomCellCount[room];
        for (int k = s; k < s + n; k++)
        {
            int a = roomCells[k];
            if (solid[a] > 0) continue;
            int ax = a % IW, az = a / IW;
            if (ax + 1 >= IW || az + 1 >= IH) continue;
            int b = a + 1, c = a + IW, d = a + IW + 1;
            if (innerRoom[b] != room || innerRoom[c] != room || innerRoom[d] != room) continue;
            if (solid[b] > 0 || solid[c] > 0 || solid[d] > 0) continue;
            wideMark[a] = wideStamp; wideMark[b] = wideStamp; wideMark[c] = wideStamp; wideMark[d] = wideStamp;
        }
    }

    bool WideCell(int room, int i)
    {
        int ix = i % IW, iz = i / IW;
        for (int oz = -1; oz <= 0; oz++)
            for (int ox = -1; ox <= 0; ox++)
            {
                int x = ix + ox, z = iz + oz;
                if (x < 0 || z < 0 || x + 1 >= IW || z + 1 >= IH) continue;
                int a = z * IW + x;
                if (innerRoom[a] == room && innerRoom[a + 1] == room && innerRoom[a + IW] == room && innerRoom[a + IW + 1] == room
                    && solid[a] == 0 && solid[a + 1] == 0 && solid[a + IW] == 0 && solid[a + IW + 1] == 0) return true;
            }
        return false;
    }

    // marks the free cells of the room connected to `start` with walkStamp; returns how many.
    // wide = 1: only through cells of the wide floor (the start cell counts as one)
    int FloodRoom(int room, int start, int wide)
    {
        int qh = 0, qt = 0;
        dist[start] = walkStamp; queue[qt++] = start;
        // the four neighbours written out (N, E, S, W): this is the generator's hottest loop, and in Udon every
        // array read and loop step is a call
        while (qh < qt)
        {
            int i = queue[qh++];
            int ix = i % IW, iz = i / IW, j;
            if (iz + 1 < IH)
            {
                j = i + IW;
                if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && (wide == 0 || wideMark[j] == wideStamp)) { dist[j] = walkStamp; queue[qt++] = j; }
            }
            if (ix + 1 < IW)
            {
                j = i + 1;
                if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && (wide == 0 || wideMark[j] == wideStamp)) { dist[j] = walkStamp; queue[qt++] = j; }
            }
            if (iz > 0)
            {
                j = i - IW;
                if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && (wide == 0 || wideMark[j] == wideStamp)) { dist[j] = walkStamp; queue[qt++] = j; }
            }
            if (ix > 0)
            {
                j = i - 1;
                if (innerRoom[j] == room && solid[j] <= 0 && dist[j] != walkStamp && (wide == 0 || wideMark[j] == wideStamp)) { dist[j] = walkStamp; queue[qt++] = j; }
            }
        }
        return qt;
    }

    // Keeps what was placed since emit index `first` if the room is still walkable and, unless the piece is
    // exempt (mandatory pieces and wrong-category spawns), not blocked beyond its cover. If not, the chairs and
    // seats that came with a new host are given up one by one, last first; if that does not help, everything
    // placed since `first` is taken away again.
    bool KeepIfWalkable(int room, int first, bool exempt)
    {
        hq_KeepIfWalkable_room = room;
        hq_KeepIfWalkable_first = first;
        hq_KeepIfWalkable_exempt = exempt;
        PhSubReset();
        bool fin = false;
        while (!fin) { PhPush(); KeepIfWalkable_Body(); fin = PhAdvance(); PhPop(); }
        return hq_KeepIfWalkable_ret;
    }

    // KeepIfWalkable in phases, a step a call (autophase4); KeepIfWalkable() above runs them to the end
    void KeepIfWalkable_Body()
    {
        planMax = 10;
        if (planPhase == 0 && PhLoop(0, 100000))
        {
            int room = hq_KeepIfWalkable_room;
            bool ht1 = false;
            if (planIter == 0) { hq_RoomWalkable_room = room; PhSubReset(); }
            PhPush(); RoomWalkable_Body(); bool fin = PhAdvance(); PhPop();
            if (fin) { ht1 = hq_RoomWalkable_ret; PhBreak(); }
            hq_KeepIfWalkable_room = room;
            hq_KeepIfWalkable_ht1 = ht1;
        }
        if (planPhase == 1)
        {
            int room = hq_KeepIfWalkable_room;
            bool exempt = hq_KeepIfWalkable_exempt;
            bool ht1 = hq_KeepIfWalkable_ht1;
            if (ht1 && (exempt || walkBlocked <= roomCoverMax[room]))
            {
                { hq_KeepIfWalkable_ret = true; hq_KeepIfWalkable_room = room; hq_KeepIfWalkable_exempt = exempt; hq_KeepIfWalkable_ht1 = ht1; PhEnd(); return; }
            }
            hq_KeepIfWalkable_room = room;
            hq_KeepIfWalkable_exempt = exempt;
            hq_KeepIfWalkable_ht1 = ht1;
        }
        // is it one chair that is in the way? Then only that one goes
        if (planPhase == 2 && PhLoop(2, 100000))
        {
            int first = hq_KeepIfWalkable_first;
            if (!PhSubActive())
            {
                if (planIter == 0) hq_KeepIfWalkable_c0 = nEmit - 1;
                int c = hq_KeepIfWalkable_c0 - planIter;
                if (!(c > first)) PhBreak();
                else { hq_KeepIfWalkable_c = c; PhSubBegin(); }
            }
            hq_KeepIfWalkable_first = first;
            if (PhSubActive())
            {
                PhPush(); KeepIfWalkable_L1(); bool fin = PhAdvance(); PhPop();
                if (fin) PhSubEnd(); else PhStay();
                if (phBreak) { phBreak = false; PhBreak(); }
                if (phReturn) { phReturn = false; PhEnd(); return; }
            }
        }
        if (planPhase == 3 && PhLoop(3, 100000))
        {
            int first = hq_KeepIfWalkable_first;
            if (!PhSubActive())
            {
                if (planIter == 0) hq_KeepIfWalkable_c0 = nEmit - 1;
                int c = hq_KeepIfWalkable_c0 - planIter;
                if (!(c > first)) PhBreak();
                else { hq_KeepIfWalkable_c = c; PhSubBegin(); }
            }
            hq_KeepIfWalkable_first = first;
            if (PhSubActive())
            {
                PhPush(); KeepIfWalkable_L2(); bool fin = PhAdvance(); PhPop();
                if (fin) PhSubEnd(); else PhStay();
                if (phBreak) { phBreak = false; PhBreak(); }
                if (phReturn) { phReturn = false; PhEnd(); return; }
            }
        }
        if (planPhase == 4)
        {
            int room = hq_KeepIfWalkable_room;
            hq_KeepIfWalkable_sel2 = 0;
            hq_KeepIfWalkable_room = room;
        }
        // the room as the walkway test saw it: # blocked, . free, d doorway floor, digits = cut-off pocket cells
        if (planPhase == 5 && PhLoop(5, 100000))
        {
            if (!(hq_KeepIfWalkable_sel2 == 1)) PhBreak();
            else
            {
                int room = hq_KeepIfWalkable_room;
                if (planIter == 0) { hq_RoomWalkable_room = room; PhSubReset(); }
                PhPush(); RoomWalkable_Body(); bool fin = PhAdvance(); PhPop();
                if (fin) {  PhBreak(); }
                hq_KeepIfWalkable_room = room;
            }
        }
        if (planPhase == 6)
        {
            if (hq_KeepIfWalkable_sel2 == 1)
            {
                int room = hq_KeepIfWalkable_room;
                for (int z = roomZ1[room]; z >= roomZ0[room]; z--)
                {
                    string line = "    ";
                    for (int x = roomX0[room]; x <= roomX1[room]; x++)
                    {
                        int i = z * IW + x;
                        line += innerRoom[i] != room ? ' ' : (solid[i] > 0 ? '#' : (dist[i] != walkStamp ? 'o' : ((tags[i] & GenData.T_DOOR_CLEAR) != 0 ? 'd' : '.')));
                    }
                }
                hq_KeepIfWalkable_room = room;
            }
        }
        if (planPhase == 7 && PhLoop(7, 100000))
        {
            int first = hq_KeepIfWalkable_first;
            if (planIter == 0) hq_KeepIfWalkable_e0 = first;
            int e = hq_KeepIfWalkable_e0 + planIter;
            if (!(e < nEmit)) PhBreak();
            else for (int once = 0; once < 1; once++)   // one pass: break and continue leave it
            {
                if (emitParent[e] < 0) Remove(e);
            }
            hq_KeepIfWalkable_first = first;
        }
        if (planPhase == 8)
        {
            statWalkRejects++;
        }
        if (planPhase == 9 && PhLoop(9, 100000))
        {
            int room = hq_KeepIfWalkable_room;
            if (planIter == 0) { hq_RoomWalkable_room = room; PhSubReset(); }
            PhPush(); RoomWalkable_Body(); bool fin = PhAdvance(); PhPop();
            if (fin) {  PhBreak(); }
            hq_KeepIfWalkable_room = room;
        }
        if (planPhase == 10)
        {
            { hq_KeepIfWalkable_ret = false; PhEnd(); return; }
        }
    }
    void KeepIfWalkable_L1()
    {
        planMax = 3;
        if (planPhase == 0)
        {
            int room = hq_KeepIfWalkable_room;
            int first = hq_KeepIfWalkable_first;
            bool exempt = hq_KeepIfWalkable_exempt;
            int c = hq_KeepIfWalkable_c;
            if (emitParent[c] < first || (emitFlags[c] & (EF_REMOVED | EF_ADJACENT)) != EF_ADJACENT) { hq_KeepIfWalkable_room = room; hq_KeepIfWalkable_first = first; hq_KeepIfWalkable_exempt = exempt; PhEnd(); return; }
            Account(c, -1);
            bool fixedIt = RoomWalkable(room) && (exempt || walkBlocked <= roomCoverMax[room]);
            Account(c, 1);
            hq_KeepIfWalkable_sel1 = 0;
            if (fixedIt) hq_KeepIfWalkable_sel1 = 1;
            hq_KeepIfWalkable_room = room;
            hq_KeepIfWalkable_first = first;
            hq_KeepIfWalkable_exempt = exempt;
        }
        if (planPhase == 1)
        {
            if (hq_KeepIfWalkable_sel1 == 1)
            {
                int c = hq_KeepIfWalkable_c;
                Remove(c);
            }
        }
        if (planPhase == 2 && PhLoop(2, 100000))
        {
            if (!(hq_KeepIfWalkable_sel1 == 1)) PhBreak();
            else
            {
                int room = hq_KeepIfWalkable_room;
                if (planIter == 0) { hq_RoomWalkable_room = room; PhSubReset(); }
                PhPush(); RoomWalkable_Body(); bool fin = PhAdvance(); PhPop();
                if (fin) {  PhBreak(); }
                hq_KeepIfWalkable_room = room;
            }
        }
        if (planPhase == 3)
        {
            if (hq_KeepIfWalkable_sel1 == 1)
            {
                { hq_KeepIfWalkable_ret = true; phReturn = true; PhEnd(); return; }
            }
        }
    }

    void KeepIfWalkable_L2()
    {
        planMax = 2;
        if (planPhase == 0)
        {
            int first = hq_KeepIfWalkable_first;
            int c = hq_KeepIfWalkable_c;
            if (emitParent[c] < first || (emitFlags[c] & EF_REMOVED) != 0) { hq_KeepIfWalkable_first = first; PhEnd(); return; }
            Remove(c);
            hq_KeepIfWalkable_first = first;
        }
        if (planPhase == 1 && PhLoop(1, 100000))
        {
            int room = hq_KeepIfWalkable_room;
            bool ht2 = false;
            if (planIter == 0) { hq_RoomWalkable_room = room; PhSubReset(); }
            PhPush(); RoomWalkable_Body(); bool fin = PhAdvance(); PhPop();
            if (fin) { ht2 = hq_RoomWalkable_ret; PhBreak(); }
            hq_KeepIfWalkable_room = room;
            hq_KeepIfWalkable_ht2 = ht2;
        }
        if (planPhase == 2)
        {
            int room = hq_KeepIfWalkable_room;
            bool exempt = hq_KeepIfWalkable_exempt;
            bool ht2 = hq_KeepIfWalkable_ht2;
            if (ht2 && (exempt || walkBlocked <= roomCoverMax[room]))
            {
                { hq_KeepIfWalkable_ret = true; hq_KeepIfWalkable_room = room; hq_KeepIfWalkable_exempt = exempt; hq_KeepIfWalkable_ht2 = ht2; phReturn = true; PhEnd(); return; }
            }
            hq_KeepIfWalkable_room = room;
            hq_KeepIfWalkable_exempt = exempt;
            hq_KeepIfWalkable_ht2 = ht2;
        }
    }


    // =====================================================================================================
    // Ground (G30): what the floor of every inner cell is made of. Outdoors the kinds blend at their borders.
    // =====================================================================================================
    public const int GR_NONE = 0, GR_INDOOR = 1, GR_LAWN = 2, GR_FOREST = 3, GR_SOIL = 4, GR_PAVING = 5, GR_TRACK = 6, GR_RELEASE = 7, GR_WATER = 8, GR_DECK = 9;
    public byte[] ground;

    int BaseGround(int i)
    {
        int t = tags[i];
        if ((t & GenData.T_FLOOR) == 0) return GR_NONE;
        if ((t & GenData.T_OUTDOOR) == 0) return GR_INDOOR;
        int room = innerRoom[i], zone = roomZone[room];
        if (zone == GenData.Z_RELEASE) return GR_RELEASE;
        if (roomType[room] == GenData.R_LANE) return GR_TRACK;    // the lane is a track (G32)
        if (roomType[room] == GenData.R_YARD) return GR_PAVING;   // a yard is paved
        if (roomType[room] == GenData.R_FORECOURT) return GR_PAVING;   // so is a forecourt (revision 9)
        if (roomType[room] == GenData.R_FARMYARD) return GR_TRACK;     // a farmyard is trodden earth
        if (roomType[room] == GenData.R_PARK && (t & GenData.T_PATH) != 0) return GR_TRACK;   // a park's gravel paths
        if ((t & GenData.T_WATER) != 0) return GR_WATER;                                     // a pond (revision 10)
        if (roomType[room] == GenData.R_TERRACE || roomType[room] == GenData.R_PLAYGROUND) return GR_PAVING;
        // revision 12: the zoo's plaza and the keepers' yard are paved, its walk is gravel, the savanna dry earth; the
        // cabin's porch is decking, its wood yard trodden earth
        int rt = roomType[room];
        if (rt == GenData.R_ZOO_PLAZA || rt == GenData.R_KEEPER || rt == GenData.R_MIDWAY || rt == GenData.R_RIDES) return GR_PAVING;
        if (rt == GenData.R_ZOO_WALK || rt == GenData.R_ENC_SAVANNA || rt == GenData.R_WOODYARD) return GR_TRACK;
        if (rt == GenData.R_PORCH) return GR_DECK;
        if (rt == GenData.R_DRYING) return GR_PAVING;   // revision 29: the drying yard is a paved standing
        if (rt == GenData.R_SCENERY) return (t & GenData.T_PATH) != 0 ? GR_LAWN : GR_FOREST;   // revision 30: scenery ground reads as planted
        if ((t & GenData.T_EARTH) != 0) return GR_TRACK;                 // trodden earth around a fire
        if (zone == GenData.Z_FOREST) return (t & GenData.T_PATH) != 0 ? GR_TRACK : GR_FOREST;
        if ((t & GenData.T_COVERED) != 0) return GR_PAVING;
        if ((t & GenData.T_SOFT_GROUND) != 0) return GR_SOIL;
        return GR_LAWN;
    }

    // The kind of every cell, then the borders between two kinds of natural ground (lawn, forest floor, soil, the
    // trodden track) are frayed: a cell next to another kind takes that kind with a chance of 38%, a cell two away
    // with 14%. The chance comes from a hash of the seed and the cell, so it is the same on every machine and needs
    // no state. Paving (a patio, a forecourt, a yard) never blends (the G30 amendment: "outside tile areas don't
    // necessarily need blending"): its edge stays where its area ends, and the natural ground beside it frays only
    // with other natural ground. Walls and fences are not borders.
    void BuildGround()
    {
        int n = IW * IH;
        if (ground == null || ground.Length != n) ground = new byte[n];
        for (int i = 0; i < n; i++) { ground[i] = (byte)BaseGround(i); dist[i] = ground[i]; }
        for (int i = 0; i < n; i++)
        {
            int g = dist[i];
            if (g < GR_LAWN || g == GR_RELEASE || g == GR_PAVING || g == GR_WATER || g == GR_DECK) continue;
            int ix = i % IW, iz = i / IW;
            int other = 0, away = 3;
            for (int d = 0; d < 4 && away > 1; d++)
                for (int step = 1; step <= 2; step++)
                {
                    int jx = ix + DX[d] * step, jz = iz + DZ[d] * step;
                    if (jx < 0 || jz < 0 || jx >= IW || jz >= IH) break;
                    // a wall or a fence between the two cells is not a border to blend across
                    if (!CanStep(ix + DX[d] * (step - 1), iz + DZ[d] * (step - 1), d)) break;
                    int gj = dist[jz * IW + jx];
                    if (gj < GR_LAWN || gj == GR_RELEASE || gj == GR_PAVING || gj == GR_WATER || gj == GR_DECK) break;
                    if (gj != g && step < away) { away = step; other = gj; }
                    if (gj != g) break;
                }
            if (other == 0) continue;
            uint h = UMod(Hash32(seed, U32(GenData.GEN_VERSION), 77, U32(i), U32(size)), 100u);
            if (h < (away == 1 ? 38u : 14u)) ground[i] = (byte)other;
        }
    }

    // one cell of BuildGround's blending pass
    void BlendGround(int i)
    {
            int g = dist[i];
            if (g < GR_LAWN || g == GR_RELEASE || g == GR_PAVING || g == GR_WATER || g == GR_DECK) return;
            int ix = i % IW, iz = i / IW;
            int other = 0, away = 3;
            for (int d = 0; d < 4 && away > 1; d++)
                for (int step = 1; step <= 2; step++)
                {
                    int jx = ix + DX[d] * step, jz = iz + DZ[d] * step;
                    if (jx < 0 || jz < 0 || jx >= IW || jz >= IH) break;
                    // a wall or a fence between the two cells is not a border to blend across
                    if (!CanStep(ix + DX[d] * (step - 1), iz + DZ[d] * (step - 1), d)) break;
                    int gj = dist[jz * IW + jx];
                    if (gj < GR_LAWN || gj == GR_RELEASE || gj == GR_PAVING || gj == GR_WATER || gj == GR_DECK) break;
                    if (gj != g && step < away) { away = step; other = gj; }
                    if (gj != g) break;
                }
            if (other == 0) return;
            uint h = UMod(Hash32(seed, U32(GenData.GEN_VERSION), 77, U32(i), U32(size)), 100u);
            if (h < (away == 1 ? 38u : 14u)) ground[i] = (byte)other;
        }

    uint Fnv(uint h, int v)
    {
        uint u = U32(v);
        for (int i = 0; i < 4; i++) { h ^= (u >> (i * 8)) & 0xFF; h *= 16777619u; }
        return h;
    }

